//! Broker configuration: TOML, generated by the `my.slop-broker` NixOS module. Durations are
//! written like `"5m"` or `"1h"` (plain numbers are seconds).
use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

use anyhow::Context;
use serde::{Deserialize, Deserializer};

use crate::policy::OpPolicy;
use crate::queue::parse_duration;

#[derive(Debug, Clone, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Config {
    pub requesters: BTreeMap<String, Requester>,
    /// Named policies; several requesters can share one.
    #[serde(default)]
    pub policies: BTreeMap<String, Policy>,
    /// Seconds a request waits for an approver.
    #[serde(default = "default_timeout", deserialize_with = "duration")]
    pub timeout: u64,
    /// Pending requests across all requesters.
    #[serde(default = "default_max_pending")]
    pub max_pending: usize,
    #[serde(default)]
    pub vsock_port: Option<u32>,
    /// Unix socket for local requesters, identified by UID.
    #[serde(default)]
    pub request_socket: Option<PathBuf>,
    pub approve_socket: PathBuf,
    /// Group whose members may answer requests.
    pub approver_group: String,
    #[serde(default)]
    pub audit_log: Option<PathBuf>,
    #[serde(default)]
    pub ssh: Option<SshConfig>,
    #[serde(default)]
    pub home_assistant: Option<HomeAssistantConfig>,
}

fn default_timeout() -> u64 {
    300
}

fn default_max_pending() -> usize {
    64
}

#[derive(Debug, Clone, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Requester {
    #[serde(default)]
    pub vsock_cid: Option<u32>,
    #[serde(default)]
    pub uid: Option<u32>,
    /// The name of its entry in `policies`.
    pub policy: String,
}

/// What a requester may do. Limits are counted for each requester on its own, as are leases.
#[derive(Debug, Clone, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Policy {
    #[serde(default = "default_requester_pending")]
    pub max_pending: usize,
    /// Requests per minute that policy approves automatically.
    #[serde(default = "default_auto_per_minute")]
    pub auto_per_minute: usize,
    /// Operations that may be used; anything missing is denied.
    #[serde(default)]
    pub ops: BTreeMap<String, OpPolicy>,
}

fn default_requester_pending() -> usize {
    4
}

fn default_auto_per_minute() -> usize {
    60
}

#[derive(Debug, Clone, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct SshConfig {
    pub ssh: PathBuf,
    /// Private key; relative paths are resolved in `$CREDENTIALS_DIRECTORY`.
    pub key: PathBuf,
    pub known_hosts: PathBuf,
    /// Named targets (deploy-rs nodes).
    pub targets: BTreeMap<String, SshTarget>,
}

#[derive(Debug, Clone, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct SshTarget {
    pub hostname: String,
    pub user: String,
    #[serde(default)]
    pub ssh_opts: Vec<String>,
}

#[derive(Debug, Clone, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct HomeAssistantConfig {
    pub url: String,
    /// Companion notification service, without the `notify.` prefix.
    pub notify_service: String,
    pub device_id: String,
    /// Long-lived access token; relative paths are resolved in `$CREDENTIALS_DIRECTORY`.
    pub token: PathBuf,
}

/// A duration in seconds, written as `"5m"` or as a number of seconds.
pub fn duration<'de, D: Deserializer<'de>>(deserializer: D) -> Result<u64, D::Error> {
    #[derive(Deserialize)]
    #[serde(untagged)]
    enum Raw {
        Seconds(u64),
        Text(String),
    }

    match Raw::deserialize(deserializer)? {
        Raw::Seconds(0) => Err(serde::de::Error::custom("duration must be positive")),
        Raw::Seconds(seconds) => Ok(seconds),
        Raw::Text(text) => parse_duration(&text)
            .ok_or_else(|| serde::de::Error::custom(format!("invalid duration {text:?}; use e.g. 30s, 5m, 1h or 1d"))),
    }
}

pub fn durations<'de, D: Deserializer<'de>>(deserializer: D) -> Result<Vec<u64>, D::Error> {
    #[derive(Deserialize)]
    struct Item(#[serde(deserialize_with = "duration")] u64);
    Ok(Vec::<Item>::deserialize(deserializer)?.into_iter().map(|i| i.0).collect())
}

pub fn optional_durations<'de, D: Deserializer<'de>>(deserializer: D) -> Result<Option<Vec<u64>>, D::Error> {
    durations(deserializer).map(Some)
}

/// Resolves a credential path the way systemd's `LoadCredential` exposes it.
pub fn credential(path: &std::path::Path) -> PathBuf {
    if path.is_absolute() {
        return path.to_owned();
    }
    let directory = std::env::var_os("CREDENTIALS_DIRECTORY").unwrap_or_default();
    PathBuf::from(directory).join(path)
}

/// Looks up a group's GID by name.
pub fn group_id(name: &str) -> anyhow::Result<u32> {
    let name = std::ffi::CString::new(name)?;
    let group = unsafe { libc::getgrnam(name.as_ptr()) };
    anyhow::ensure!(!group.is_null(), "unknown group {name:?}");
    Ok(unsafe { (*group).gr_gid })
}

/// A user's name, for showing who answered a request.
pub fn user_name(uid: u32) -> String {
    let mut buffer = vec![0; 4096];
    let mut entry: libc::passwd = unsafe { std::mem::zeroed() };
    let mut result = std::ptr::null_mut();

    let status = unsafe { libc::getpwuid_r(uid, &mut entry, buffer.as_mut_ptr(), buffer.len(), &mut result) };
    if status != 0 || result.is_null() {
        return format!("uid {uid}");
    }
    unsafe { std::ffi::CStr::from_ptr(entry.pw_name) }.to_string_lossy().into_owned()
}

impl Config {
    pub fn load(path: &Path) -> anyhow::Result<Config> {
        let text = std::fs::read_to_string(path).with_context(|| format!("reading {}", path.display()))?;
        toml::from_str(&text).with_context(|| format!("parsing {}", path.display()))
    }

    /// Checks what the types can't: every requester's policy exists.
    pub fn validate(&self) -> anyhow::Result<()> {
        for (name, requester) in &self.requesters {
            anyhow::ensure!(
                self.policies.contains_key(&requester.policy),
                "requester {name:?} has policy {:?}, which isn't configured",
                requester.policy
            );
        }
        Ok(())
    }

    pub fn policy(&self, requester: &str) -> Option<&Policy> {
        self.policies.get(&self.requesters.get(requester)?.policy)
    }

    pub fn requester_by_cid(&self, cid: u32) -> Option<&str> {
        self.requesters.iter().find(|(_, r)| r.vsock_cid == Some(cid)).map(|(n, _)| n.as_str())
    }

    pub fn requester_by_uid(&self, uid: u32) -> Option<&str> {
        self.requesters.iter().find(|(_, r)| r.uid == Some(uid)).map(|(n, _)| n.as_str())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The layout the NixOS module writes.
    #[test]
    fn parses_generated_config() {
        let config: Config = toml::from_str(
            r#"
            approve_socket = "/run/slop-broker/approve.sock"
            approver_group = "slop-broker-approve"
            timeout = "5m"

            [requesters.slop-cannon]
            vsock_cid = 3
            policy = "agent"

            [policies.agent.ops.query]
            action = "auto"

            [policies.agent.ops.ssh]
            action = "ask"
            leases = ["5m", "1h"]

            [[policies.agent.ops.ssh.rules]]
            action = "deny"
            leases = [600]
            match = { target = "river" }
            "#,
        )
        .unwrap();

        config.validate().unwrap();
        assert_eq!(config.timeout, 300);

        let ssh = &config.policy("slop-cannon").unwrap().ops["ssh"];
        assert_eq!(ssh.leases, [300, 3600]);
        assert_eq!(ssh.rules[0].leases, Some(vec![600]));

        assert!(
            toml::from_str::<Config>("approve_socket = \"/a\"\napprover_group = \"g\"\ntimeout = \"5\"\n").is_err()
        );
        assert!(toml::from_str::<Config>("approve_socket = \"/a\"\napprover_group = \"g\"\nunknown = 1\n").is_err());

        let mut missing = config.clone();
        missing.policies.clear();
        assert!(missing.validate().is_err());
    }
}
